  /** 130. Taker's one-time X25519 key. */
  takerEncKey: Uint8Array;
  /** 162. Maker key version the swap's messages use. */
  makerEncVersion: number;
  /** 166. The maker's X25519 key of that version, copied from the Maker account. */
  makerEncKey: Uint8Array;
  /** 198 */
  amount: bigint;
  deposit: bigint;
  xmr: bigint;
  price: bigint;
  /** 230 */
  depBps: number;
  feeBps: number;
  /** 234 */
  wN: number;
  dC: number;
  wC: number;
  /** 246 */
  takerSpendPub: Uint8Array;
  /** 278. Zeros until known. */
  makerSpendPub: Uint8Array;
  /** 310. The locker's private view share, in clear. */
  lockerView: Uint8Array;
  /** 342 */
  noticeCommitment: Uint8Array;
  /** 374 */
  noticeCt: Uint8Array;
  /** 478 */
  evidenceTxid: Uint8Array;
  evidenceView: Uint8Array;
  /** 542. The revealed spend share. */
  revealed: Uint8Array;
  /** 574. 0 = not set. */
  tLock: bigint;
  tPendingDeadline: bigint;
  tActive: bigint;
  tNoteDeadline: bigint;
  tNotice: bigint;
  tCut: bigint;
  tClaimOpen: bigint;
  tReady: bigint;
